=== README.md
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

## Usage

```sh
terraform init
terraform apply
```

State is kept locally in `terraform.tfstate`, so only the person who last ran `apply` has it.
=== main.tf
resource "aws_s3_bucket" "reports" {
  bucket = "reports-${var.environment}"
}

resource "aws_s3_bucket_lifecycle_configuration" "reports" {
  bucket = aws_s3_bucket.reports.id

  rule {
    id     = "expire-old-reports"
    status = "Enabled"

    filter {}

    expiration {
      days = 90
    }
  }
}

resource "aws_iam_user" "uploader" {
  name = "reports-uploader-${var.environment}"
}

resource "aws_iam_access_key" "uploader" {
  user = aws_iam_user.uploader.name
}
=== outputs.tf
output "uploader_access_key_id" {
  value = aws_iam_access_key.uploader.id
}

output "uploader_secret_access_key" {
  value     = aws_iam_access_key.uploader.secret
  sensitive = true
}
=== providers.tf
provider "aws" {
  region = var.region
}
=== variables.tf
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "environment" {
  type    = string
  default = "staging"
}
=== versions.tf
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

