  name          = "alias/reports-tfstate"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-old-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_expiration_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > bootstrap/outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  value = aws_kms_key.state.arn
}

output "init_command" {
  description = "Run this in the root configuration to point it at the state bucket."
  value       = "terraform init -migrate-state -backend-config=\"bucket=${aws_s3_bucket.state.id}\" -backend-config=\"kms_key_id=${aws_kms_key.state.arn}\""
}
EOF
cat > backend.tf <<'EOF'
# bucket and kms_key_id are supplied at init time; see README.md.
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

State is stored in S3 (versioned, KMS-encrypted, TLS-only, locked with S3 native lockfiles), so
anyone with access to the bucket and key can run `plan` and `apply`. The state contains the
uploader's secret access key: grant bucket and KMS access only to people who may read that secret.

## One-time setup (bootstrap)

`bootstrap/` creates the state bucket and KMS key. Its own state stays local, because it cannot
live in a bucket that does not exist yet; it holds no secrets. Run it once, by one person, and
commit nothing from it except the `.tf` files (`*.tfstate` is gitignored).

```sh
cd bootstrap
terraform init
terraform apply
terraform output -raw init_command
```

The bucket defaults to `reports-tfstate-<account id>`; override with `-var state_bucket_name=...`.
The bucket has `prevent_destroy` set.

## Migrating the existing local state

From the person who holds the current `terraform.tfstate`, in the repo root:

```sh
$(cd bootstrap && terraform output -raw init_command)
# answer "yes" to copy the existing state to the new backend
terraform plan   # should show no changes
```

Then confirm the object exists in S3 and delete the local `terraform.tfstate*` files.

## Daily workflow (everyone else)

Each team member needs AWS credentials with `s3:ListBucket` on the bucket, `s3:GetObject`,
`s3:PutObject` and `s3:DeleteObject` on `reports/*` (the lockfile is `terraform.tfstate.tflock`),
and `kms:Encrypt`/`kms:Decrypt`/`kms:GenerateDataKey` on the state key.

```sh
terraform init -backend-config="bucket=<state bucket>" -backend-config="kms_key_id=<key arn>"
terraform plan
terraform apply
```

(Both values are printed by `terraform output` in `bootstrap/`.) Locking is automatic; if a run
is interrupted, use `terraform force-unlock <id>`.
EOF
which terraform && terraform fmt -recursive && (cd bootstrap && terraform init -backend=false >/dev/null && terraform validate)
